// Highly dangerous: relying on finalize() to release native or file resources
import java.io.FileInputStream;
import java.io.IOException;

public class ResourceHolder {
    private FileInputStream stream;

    public ResourceHolder(String file) throws IOException {
        this.stream = new FileInputStream(file);
    }

    // Deprecated, unpredictable, and can permanently leak file descriptors!
    @Override
    protected void finalize() throws Throwable {
        try {
            if (stream != null) stream.close();
        } finally {
            super.finalize();
        }
    }
}

