    public static void main(String[] args) throws Exception {
        // If instances are created faster than the finalizer queue thread runs,
        // the OS runs out of file descriptors and crashes long before GC runs!
        for (int i = 0; i < 100_000; i++) {
            new ResourceHolder("data.txt");
        }
    }
}

right_code.class:
// Clean and safe: implement AutoCloseable with try-with-resources
import java.io.FileInputStream;
import java.io.IOException;

public class ResourceHolder implements AutoCloseable {
    private FileInputStream stream;
    private boolean closed = false;

    public ResourceHolder(String file) throws IOException {
        this.stream = new FileInputStream(file);
    }

    @Override
    public void close() throws IOException {
        if (!closed) {
            closed = true;
            if (stream != null) stream.close();
        }
    }
}

